import queue
from pymavlink import mavutil
import socketio
import requests

class FlightControlsWebSocketTest:
    def __init__(self):
        self.webgcs_url = "http://localhost:5001"
        self.virtual_drone_address = "tcp:192.168.193.235:5678"
        self.sio = socketio.Client()
        self.mavlink_conn = None

