            return all_passed

        except Exception as e:
            logger.error(f"❌ Test execution failed: {e}")
            return False
        finally:
            self.cleanup()

def main():
    """Main entry point"""
    agent = MapInterfaceTestAgent()
    return asyncio.run(agent.run_all_tests())

if __name__ == "__main__":
    success = main()
    exit(0 if success else 1)

